import numpy as np
from .base import BaseLayer


class MaxPool2D(BaseLayer):
    def __init__(self, kernel_size: int, stride: int = None):
        self.kernel_size = kernel_size
        if stride is None:
            self.stride = kernel_size
        else:
            self.stride = stride

    def forward(self, x: np.ndarray) -> np.ndarray:
        batch_size = x.shape[0]
        height = x.shape[1]
        width = x.shape[2]
        channels = x.shape[3]

        out_height = (height - self.kernel_size) // self.stride + 1
        out_width = (width - self.kernel_size) // self.stride + 1

        output = np.zeros((batch_size, out_height, out_width, channels), dtype=np.float64)

        for b in range(batch_size):
            for i in range(out_height):
                for j in range(out_width):
                    start_h = i * self.stride
                    start_w = j * self.stride
                    end_h = start_h + self.kernel_size
                    end_w = start_w + self.kernel_size

                    window = x[b, start_h:end_h, start_w:end_w, :]
                    max_val = np.max(window, axis=(0, 1))
                    output[b, i, j, :] = max_val

        return output.astype(np.float64)


class AvgPool2D(BaseLayer):
    def __init__(self, kernel_size: int, stride: int = None):
        self.kernel_size = kernel_size
        if stride is None:
            self.stride = kernel_size
        else:
            self.stride = stride

